SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM ip_pool_status ips
    WHERE ips.security_code = #{companyCode}
      AND ips.security_type = 'company'
      AND ips.target_pool_id = #{poolId}
      AND ips.audit_status = '20'
      AND ips.is_deleted = 0
) THEN 1 ELSE 0 END

SELECT CASE WHEN EXISTS ( SELECT 1 FROM ais_inv_ods.wind_cbondissuerrating r WHERE r.s_info_compcode = #{companyCode}
AND r.b_info_creditratingagency IN
#{agencyCode}
AND 1 = 0
AND COALESCE(NULLIF(r.ann_dt2, ''), NULLIF(r.ann_dt, ''), '00000000') >= DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 1 YEAR), '%Y%m%d') AND TRIM(r.b_info_creditrating) IN ( 'AA-', 'A+', 'A', 'A-' ,'BBB+', 'BBB', 'BBB-' ,'BB+', 'BB', 'BB-' ,'B+', 'B', 'B-' ,'CCC', 'CC', 'C', 'D' ) ) THEN 1 ELSE 0 END
